FIX: Filter out off-screen placeholders (y + cy > slideHeight) before computing normalization target. Use the highest visible Y position instead of the absolute max:

  func normalizeFooterVerticalPositions(positions map[string]*transformXML) {
      var visibleY, maxCY int64
      for _, pos := range positions {
          if pos.Offset.Y + pos.Extent.CY <= defaultSlideHeightEMU {
              if pos.Offset.Y > visibleY { visibleY = pos.Offset.Y }
          }
          if pos.Extent.CY > maxCY { maxCY = pos.Extent.CY }
      }
      // apply visibleY to all visible positions
  }

